import{_ as t,o as s,c as a,ak as o}from"./chunks/framework.BHDkgpnK.js";const p=JSON.parse('{"title":"KossJS Python 接口封装使用文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh/interface/py/how-to-use.md","filePath":"zh/interface/py/how-to-use.md","lastUpdated":1786014703000}'),r={name:"zh/interface/py/how-to-use.md"};function n(l,e,i,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kossjs-python-接口封装使用文档" tabindex="-1">KossJS Python 接口封装使用文档 <a class="header-anchor" href="#kossjs-python-接口封装使用文档" aria-label="Permalink to “KossJS Python 接口封装使用文档”">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>本文档介绍 KossJS 的 Python 接口封装 <em><strong>kossjs_interface.py</strong></em>。</p></div><h2 id="_0-安装说明" tabindex="-1">0. 安装说明 <a class="header-anchor" href="#_0-安装说明" aria-label="Permalink to “0. 安装说明”">​</a></h2><h3 id="_0-1-系统要求" tabindex="-1">0.1 系统要求 <a class="header-anchor" href="#_0-1-系统要求" aria-label="Permalink to “0.1 系统要求”">​</a></h3><ol><li>Python 3.11 及以上版本</li><li>KossJS 动态库文件： <ul><li>Windows 平台：<em><strong>kossjs.dll</strong></em></li><li>macOS 平台：<em><strong>libkossjs.dylib</strong></em></li><li>Linux 平台：<em><strong>libkossjs.so</strong></em></li></ul></li></ol><h3 id="_0-2-安装步骤" tabindex="-1">0.2 安装步骤 <a class="header-anchor" href="#_0-2-安装步骤" aria-label="Permalink to “0.2 安装步骤”">​</a></h3><ol><li>将动态库文件放置在项目目录中</li><li>将 <em><strong>kossjs_interface.py</strong></em> 复制到项目目录</li></ol><hr><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><ul><li><strong>核心类</strong>：<em><strong>KossJS</strong></em></li><li><strong>依赖</strong>：<em><strong>ctypes</strong></em>、<em><strong>json</strong></em>、<em><strong>pathlib</strong></em> 等标准库</li><li><strong>功能</strong>： <ul><li>创建 JS 实例（支持模块加载、能力位控制、稳定模式）</li><li>执行 JavaScript 代码</li><li>全局变量注入</li><li>注册原生函数</li><li>Fetch API 调用</li><li>沙箱安全（审核掩码、审核回调、调试模式、JS 层审核回调）</li></ul></li></ul><hr><h2 id="_2-kossjs-类" tabindex="-1">2. <em><strong>KossJS</strong></em> 类 <a class="header-anchor" href="#_2-kossjs-类" aria-label="Permalink to “2. KossJS 类”">​</a></h2><h3 id="_2-1-初始化" tabindex="-1">2.1 初始化 <a class="header-anchor" href="#_2-1-初始化" aria-label="Permalink to “2.1 初始化”">​</a></h3><p><code>python koss = KossJS( lib_path: str | None = None, with_modules: bool = False, root_dir: str | None = None, capabilities: int | None = None, stable: bool = True ) </code></p><ul><li><strong>参数</strong>: <ul><li><em><strong>lib_path</strong></em>: 动态库路径。若为 <em><strong>None</strong></em>，根据操作系统自动选择默认路径</li><li><em><strong>with_modules</strong></em>: 是否启用模块加载（默认 <em><strong>False</strong></em>）</li><li><em><strong>root_dir</strong></em>: 模块解析的根目录（默认当前目录）</li><li><em><strong>capabilities</strong></em>: 能力位掩码（默认 <em><strong>None</strong></em> = <code>KOSS_CAP_SANDBOX</code>，纯计算沙箱）。参见 <a href="/KossJS/zh/security-sandbox/security-sandbox.html">安全与沙箱指南</a></li><li><em><strong>stable</strong></em>: 稳定模式（默认 <em><strong>True</strong></em>）。<em><strong>True</strong></em> 时禁用 FFI；<em><strong>False</strong></em> 启用 FFI</li></ul></li></ul><p><strong>能力常量</strong>（28 个细粒度操作）：</p><p>`python</p><h1 id="文件系统-6-个" tabindex="-1">文件系统（6 个） <a class="header-anchor" href="#文件系统-6-个" aria-label="Permalink to “文件系统（6 个）”">​</a></h1><p>KossJS.FS_READ = 1 &lt;&lt; 0 KossJS.FS_WRITE = 1 &lt;&lt; 1 KossJS.FS_DELETE = 1 &lt;&lt; 2 KossJS.FS_MKDIR = 1 &lt;&lt; 3 KossJS.FS_RENAME = 1 &lt;&lt; 4 KossJS.FS_CHMOD = 1 &lt;&lt; 5</p><h1 id="网络-5-个" tabindex="-1">网络（5 个） <a class="header-anchor" href="#网络-5-个" aria-label="Permalink to “网络（5 个）”">​</a></h1><p>KossJS.NET_TCP_CLIENT = 1 &lt;&lt; 6 KossJS.NET_TCP_SERVER = 1 &lt;&lt; 7 KossJS.NET_UDP = 1 &lt;&lt; 8 KossJS.NET_DNS = 1 &lt;&lt; 9 KossJS.NET_FETCH = 1 &lt;&lt; 10</p><h1 id="加密-4-个" tabindex="-1">加密（4 个） <a class="header-anchor" href="#加密-4-个" aria-label="Permalink to “加密（4 个）”">​</a></h1><p>KossJS.CRYPTO_HASH = 1 &lt;&lt; 11 KossJS.CRYPTO_HMAC = 1 &lt;&lt; 12 KossJS.CRYPTO_RANDOM = 1 &lt;&lt; 13 KossJS.CRYPTO_PBKDF2 = 1 &lt;&lt; 14</p><h1 id="内置-ffi-5-个" tabindex="-1">内置 FFI（5 个） <a class="header-anchor" href="#内置-ffi-5-个" aria-label="Permalink to “内置 FFI（5 个）”">​</a></h1><p>KossJS.FFI_OPEN = 1 &lt;&lt; 15 KossJS.FFI_CALL = 1 &lt;&lt; 16 KossJS.FFI_ALLOC = 1 &lt;&lt; 17 KossJS.FFI_CALLBACK = 1 &lt;&lt; 18 KossJS.FFI_STRUCT = 1 &lt;&lt; 19</p><h1 id="其他模块-8-个" tabindex="-1">其他模块（8 个） <a class="header-anchor" href="#其他模块-8-个" aria-label="Permalink to “其他模块（8 个）”">​</a></h1><p>KossJS.NATIVE_ADDON = 1 &lt;&lt; 20 KossJS.WASM = 1 &lt;&lt; 21 KossJS.SHARED_MEMORY = 1 &lt;&lt; 22 KossJS.HIGHRES_TIME = 1 &lt;&lt; 23 KossJS.SYSINFO = 1 &lt;&lt; 24 KossJS.MODULE_LOAD = 1 &lt;&lt; 25 KossJS.DYNAMIC_CODE = 1 &lt;&lt; 26 KossJS.DEBUG_CAP = 1 &lt;&lt; 27</p><h1 id="组合常量" tabindex="-1">组合常量 <a class="header-anchor" href="#组合常量" aria-label="Permalink to “组合常量”">​</a></h1><p>KossJS.KOSS_CAP_SANDBOX = 0 KossJS.KOSS_CAP_ALL_FS = FS_READ | FS_WRITE | FS_DELETE | FS_MKDIR | FS_RENAME | FS_CHMOD KossJS.KOSS_CAP_ALL_NET = NET_TCP_CLIENT | NET_TCP_SERVER | NET_UDP | NET_DNS | NET_FETCH KossJS.KOSS_CAP_ALL_CRYPTO = CRYPTO_HASH | CRYPTO_HMAC | CRYPTO_RANDOM | CRYPTO_PBKDF2 KossJS.KOSS_CAP_ALL_FFI = FFI_OPEN | FFI_CALL | FFI_ALLOC | FFI_CALLBACK | FFI_STRUCT KossJS.KOSS_CAP_ALL = 0xFFFFFFFF</p><h1 id="兼容别名" tabindex="-1">兼容别名 <a class="header-anchor" href="#兼容别名" aria-label="Permalink to “兼容别名”">​</a></h1><p>KossJS.KOSS_CAP_FS = KossJS.KOSS_CAP_ALL_FS KossJS.KOSS_CAP_NET = KossJS.KOSS_CAP_ALL_NET KossJS.KOSS_CAP_CRYPTO = KossJS.KOSS_CAP_ALL_CRYPTO KossJS.KOSS_CAP_EXTERNAL_LOADER = KossJS.MODULE_LOAD `</p><h3 id="_2-2-实例属性" tabindex="-1">2.2 实例属性 <a class="header-anchor" href="#_2-2-实例属性" aria-label="Permalink to “2.2 实例属性”">​</a></h3><h4 id="is-stable-bool" tabindex="-1"><em><strong>is_stable -&gt; bool</strong></em> <a class="header-anchor" href="#is-stable-bool" aria-label="Permalink to “is_stable -&gt; bool”">​</a></h4><p>查询实例是否处于稳定模式。</p><p>`python koss = KossJS() print(koss.is_stable) # True</p><p>koss_dev = KossJS(stable=False) print(koss_dev.is_stable) # False `</p><h4 id="get-capabilities-int" tabindex="-1"><em><strong>get_capabilities() -&gt; int</strong></em> <a class="header-anchor" href="#get-capabilities-int" aria-label="Permalink to “get_capabilities() -&gt; int”">​</a></h4><p>查询当前实例的能力位掩码。</p><p><code>python koss = KossJS(capabilities=KossJS.KOSS_CAP_ALL_FS | KossJS.KOSS_CAP_ALL_NET) caps = koss.get_capabilities() print(f&quot;Capabilities: {caps:#010x}&quot;) </code></p><h3 id="_2-3-执行代码" tabindex="-1">2.3 执行代码 <a class="header-anchor" href="#_2-3-执行代码" aria-label="Permalink to “2.3 执行代码”">​</a></h3><h4 id="eval-code-str-any" tabindex="-1"><em><strong>eval(code: str) -&gt; Any</strong></em> <a class="header-anchor" href="#eval-code-str-any" aria-label="Permalink to “eval(code: str) -&gt; Any”">​</a></h4><p>执行 JavaScript 代码并返回结果。JSON 对象/数组自动解析。</p><p><code>python result = koss.eval(&quot;1 + 2&quot;) print(result) # 输出: 3 </code></p><h4 id="run-async-code-str-timeout-ms-int-30000-str" tabindex="-1"><em><strong>run_async(code: str, timeout_ms: int = 30000) -&gt; str</strong></em> <a class="header-anchor" href="#run-async-code-str-timeout-ms-int-30000-str" aria-label="Permalink to “run_async(code: str, timeout_ms: int = 30000) -&gt; str”">​</a></h4><p>执行异步代码并驱动事件循环直到 Promise 完成。适合 \x07wait/ etch。</p><p><code>python result = koss.run_async(&quot;&quot;&quot; (async () =&gt; { const r = await fetch(&quot;https://api.github.com/users/github&quot;); const d = await r.json(); return d.login; })(); &quot;&quot;&quot;, timeout_ms=30000) </code></p><h4 id="tick-bool" tabindex="-1"><em><strong>tick() -&gt; bool</strong></em> <a class="header-anchor" href="#tick-bool" aria-label="Permalink to “tick() -&gt; bool”">​</a></h4><p>运行事件循环单次迭代。返回 True 表示仍有未完成的异步操作。</p><p><code>python koss.eval(&quot;fetch(&#39;https://example.com/api&#39;).then(r =&gt; r.json())&quot;) while koss.tick(): pass # 手动驱动事件循环 </code></p><h4 id="run-file-path-str-str" tabindex="-1"><em><strong>run_file(path: str) -&gt; str</strong></em> <a class="header-anchor" href="#run-file-path-str-str" aria-label="Permalink to “run_file(path: str) -&gt; str”">​</a></h4><p>执行 JavaScript 文件。</p><p><code>python result = koss.run_file(&quot;./script.js&quot;) </code></p><h4 id="run-module-path-str-str" tabindex="-1"><em><strong>run_module(path: str) -&gt; str</strong></em> <a class="header-anchor" href="#run-module-path-str-str" aria-label="Permalink to “run_module(path: str) -&gt; str”">​</a></h4><p>以 ES Module 方式执行 JavaScript 文件。</p><p><code>python result = koss.run_module(&quot;./module.mjs&quot;) </code></p><h4 id="run-string-code-str-str" tabindex="-1"><em><strong>run_string(code: str) -&gt; str</strong></em> <a class="header-anchor" href="#run-string-code-str-str" aria-label="Permalink to “run_string(code: str) -&gt; str”">​</a></h4><p>执行 JavaScript 代码字符串（与 <em><strong>eval</strong></em> 相同）。</p><p><code>python result = koss.run_string(&quot;console.log(&#39;Hello&#39;)&quot;) </code></p><h4 id="run-module-string-code-str-str" tabindex="-1"><em><strong>run_module_string(code: str) -&gt; str</strong></em> <a class="header-anchor" href="#run-module-string-code-str-str" aria-label="Permalink to “run_module_string(code: str) -&gt; str”">​</a></h4><p>以 ES Module 方式执行代码字符串。</p><p><code>python result = koss.run_module_string(&#39;&#39;&#39; import { add } from &quot;./math.mjs&quot;; add(1, 2); &#39;&#39;&#39;) </code></p><h3 id="_2-4-全局变量" tabindex="-1">2.4 全局变量 <a class="header-anchor" href="#_2-4-全局变量" aria-label="Permalink to “2.4 全局变量”">​</a></h3><h4 id="set-global-name-str-value-any-none" tabindex="-1"><em><strong>set_global(name: str, value: Any) -&gt; None</strong></em> <a class="header-anchor" href="#set-global-name-str-value-any-none" aria-label="Permalink to “set_global(name: str, value: Any) -&gt; None”">​</a></h4><p>设置全局变量。支持的类型：</p><ul><li><em><strong>str</strong></em> → 全局字符串</li><li><em><strong>int/float</strong></em> → 全局数字</li><li><em><strong>bool</strong></em> → 全局布尔值</li><li><em><strong>None</strong></em> → 全局 ull</li><li><em><strong>&quot;<strong>undefined</strong>&quot;</strong></em> → 全局 undefined</li><li><em><strong>list/dict</strong></em> → 自动序列化为 JSON 对象/数组</li></ul><p><code>python koss.set_global(&quot;myVar&quot;, &quot;Hello&quot;) koss.set_global(&quot;count&quot;, 100) koss.set_global(&quot;isReady&quot;, True) koss.set_global(&quot;emptyVal&quot;, None) koss.set_global(&quot;notSet&quot;, &quot;__undefined__&quot;) koss.set_global(&quot;config&quot;, {&quot;debug&quot;: True, &quot;port&quot;: 8080}) </code></p><h3 id="_2-5-原生函数-类注册" tabindex="-1">2.5 原生函数 / 类注册 <a class="header-anchor" href="#_2-5-原生函数-类注册" aria-label="Permalink to “2.5 原生函数 / 类注册”">​</a></h3><h4 id="register-function-name-str-func-callable-any-none" tabindex="-1"><em><strong>register_function(name: str, func: Callable[..., Any]) -&gt; None</strong></em> <a class="header-anchor" href="#register-function-name-str-func-callable-any-none" aria-label="Permalink to “register_function(name: str, func: Callable[..., Any]) -&gt; None”">​</a></h4><p>将 Python 函数注册为 JavaScript 可调用。</p><p>`python def add(a, b): return str(int(a) + int(b))</p><p>koss.register_function(&quot;add&quot;, add) result = koss.eval(&quot;add(10, 20)&quot;) print(result) # 输出: 30 `</p><h4 id="register-class-class-name-str-methods-dict-str-callable-none" tabindex="-1"><em><strong>register_class(class_name: str, methods: dict[str, Callable]) -&gt; None</strong></em> <a class="header-anchor" href="#register-class-class-name-str-methods-dict-str-callable-none" aria-label="Permalink to “register_class(class_name: str, methods: dict[str, Callable]) -&gt; None”">​</a></h4><p>注册支持 ew 关键字的 JavaScript 类。</p><p>`python def greet(name=&quot;World&quot;): return f&quot;Hello, {name}!&quot;</p><p>koss.register_class(&quot;Greeter&quot;, {&quot;greet&quot;: greet}) result = koss.eval(&quot;new Greeter().greet(&#39;KossJS&#39;)&quot;) print(result) # 输出: Hello, KossJS! `</p><h3 id="_2-6-沙箱安全" tabindex="-1">2.6 沙箱安全 <a class="header-anchor" href="#_2-6-沙箱安全" aria-label="Permalink to “2.6 沙箱安全”">​</a></h3><h4 id="set-audit-mask-mask-int-none" tabindex="-1"><em><strong>set_audit_mask(mask: int) -&gt; None</strong></em> <a class="header-anchor" href="#set-audit-mask-mask-int-none" aria-label="Permalink to “set_audit_mask(mask: int) -&gt; None”">​</a></h4><p>设置审核掩码，控制哪些 API 需要经过审核回调。</p><p><code>python koss.set_audit_mask(KossJS.FS_READ | KossJS.NET_FETCH) </code></p><h4 id="get-audit-mask-int" tabindex="-1"><em><strong>get_audit_mask() -&gt; int</strong></em> <a class="header-anchor" href="#get-audit-mask-int" aria-label="Permalink to “get_audit_mask() -&gt; int”">​</a></h4><p>获取当前审核掩码。</p><p><code>python mask = koss.get_audit_mask() </code></p><h4 id="check-sandbox-callback-callable-none-none" tabindex="-1"><em><strong>check_sandbox(callback: Callable | None) -&gt; None</strong></em> <a class="header-anchor" href="#check-sandbox-callback-callable-none-none" aria-label="Permalink to “check_sandbox(callback: Callable | None) -&gt; None”">​</a></h4><p>注册或清除审核回调。回调签名：(target: str, args: list[str], pwd: str | None) -&gt; bool</p><p>`python def my_audit(target: str, args: list[str], pwd: str | None) -&gt; bool: if target == &quot;fs.readFile&quot;: return args[0].startswith(&quot;/tmp/sandbox/&quot;) return True</p><p>koss.check_sandbox(my_audit) # 注册 koss.check_sandbox(None) # 清除 `</p><h4 id="enable-audit-debug-enable-bool-none" tabindex="-1"><em><strong>enable_audit_debug(enable: bool) -&gt; None</strong></em> <a class="header-anchor" href="#enable-audit-debug-enable-bool-none" aria-label="Permalink to “enable_audit_debug(enable: bool) -&gt; None”">​</a></h4><p>启用/禁用审核调试模式。</p><p><code>python koss.enable_audit_debug(True) # 开启 koss.enable_audit_debug(False) # 关闭 </code></p><h3 id="_2-7-js-层审核回调" tabindex="-1">2.7 JS 层审核回调 <a class="header-anchor" href="#_2-7-js-层审核回调" aria-label="Permalink to “2.7 JS 层审核回调”">​</a></h3><h4 id="clear-js-audit-str" tabindex="-1"><em><strong>clear_js_audit() -&gt; str</strong></em> <a class="header-anchor" href="#clear-js-audit-str" aria-label="Permalink to “clear_js_audit() -&gt; str”">​</a></h4><p>清除 JS 层审核回调（由 JS 侧 <code>KossJS.set_audit_callback</code> 注册）。清除后，掩码覆盖的操作由宿主审核回调单独决策。</p><p>`python</p><h1 id="js-侧注册审核回调-拒绝所有-fs-操作" tabindex="-1">JS 侧注册审核回调（拒绝所有 fs 操作） <a class="header-anchor" href="#js-侧注册审核回调-拒绝所有-fs-操作" aria-label="Permalink to “JS 侧注册审核回调（拒绝所有 fs 操作）”">​</a></h1><p>koss.eval(&quot;KossJS.set_audit_callback(function(t, a, p) { return false; })&quot;)</p><h1 id="宿主清除-js-层审核回调" tabindex="-1">宿主清除 JS 层审核回调 <a class="header-anchor" href="#宿主清除-js-层审核回调" aria-label="Permalink to “宿主清除 JS 层审核回调”">​</a></h1><p>koss.clear_js_audit() `</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Worker 线程池相关方法（<code>create_worker_pool</code>、<code>worker_execute</code> 等）自 <strong>v0.1.0-dev.10</strong> 起已从 Python 接口移除。</p></div><h3 id="_2-8-资源管理" tabindex="-1">2.8 资源管理 <a class="header-anchor" href="#_2-8-资源管理" aria-label="Permalink to “2.8 资源管理”">​</a></h3><h4 id="destroy-none" tabindex="-1"><em><strong>destroy() -&gt; None</strong></em> <a class="header-anchor" href="#destroy-none" aria-label="Permalink to “destroy() -&gt; None”">​</a></h4><p>销毁 JS 实例并释放内存。</p><p><code>python koss.destroy() </code></p><h5 id="上下文管理器支持" tabindex="-1">上下文管理器支持 <a class="header-anchor" href="#上下文管理器支持" aria-label="Permalink to “上下文管理器支持”">​</a></h5><p>`python with KossJS() as koss: result = koss.eval(&quot;1 + 1&quot;) print(result)</p><h1 id="自动销毁" tabindex="-1">自动销毁 <a class="header-anchor" href="#自动销毁" aria-label="Permalink to “自动销毁”">​</a></h1><p>`</p><h3 id="_2-9-其他方法" tabindex="-1">2.9 其他方法 <a class="header-anchor" href="#_2-9-其他方法" aria-label="Permalink to “2.9 其他方法”">​</a></h3><h4 id="version-str" tabindex="-1"><em><strong>version() -&gt; str</strong></em> <a class="header-anchor" href="#version-str" aria-label="Permalink to “version() -&gt; str”">​</a></h4><p>获取 KossJS 版本。</p><p><code>python print(koss.version()) # 输出: 0.1.0-dev.10 </code></p><hr><h2 id="_3-异常处理" tabindex="-1">3. 异常处理 <a class="header-anchor" href="#_3-异常处理" aria-label="Permalink to “3. 异常处理”">​</a></h2><h3 id="jserror" tabindex="-1">JsError <a class="header-anchor" href="#jserror" aria-label="Permalink to “JsError”">​</a></h3><p>当 JavaScript 代码执行抛出错误时，会引发 <em><strong>JsError</strong></em> 异常。</p><p>`python from kossjs_interface import KossJS, JsError</p><p>try: koss.eval(&quot;throw new Error(&#39;test error&#39;)&quot;) except JsError as e: print(f&quot;JS Error: {e}&quot;) `</p><hr><h2 id="_4-使用示例" tabindex="-1">4. 使用示例 <a class="header-anchor" href="#_4-使用示例" aria-label="Permalink to “4. 使用示例”">​</a></h2><h3 id="_4-1-基本用法" tabindex="-1">4.1 基本用法 <a class="header-anchor" href="#_4-1-基本用法" aria-label="Permalink to “4.1 基本用法”">​</a></h3><p>`python from kossjs_interface import KossJS</p><p>with KossJS() as koss: # 基本计算 result = koss.eval(&quot;1 + 2 * 3&quot;) print(result) # 输出: 7</p><pre><code># 箭头函数\ncode = &quot;(a, b) =&gt; a + b&quot;\nkoss.set_global(&quot;add&quot;, koss.eval(code))\nresult = koss.eval(&quot;add(5, 3)&quot;)\nprint(result)  # 输出: 8\n\n# 对象操作\ncode = &quot;&quot;&quot;\nconst person = { name: &quot;John&quot;, age: 30 };\nperson.name;\n&quot;&quot;&quot;\nresult = koss.eval(code)\nprint(result)  # 输出: John\n</code></pre><p>`</p><h3 id="_4-2-使用沙箱能力位" tabindex="-1">4.2 使用沙箱能力位 <a class="header-anchor" href="#_4-2-使用沙箱能力位" aria-label="Permalink to “4.2 使用沙箱能力位”">​</a></h3><p>`python from kossjs_interface import KossJS</p><h1 id="纯计算沙箱" tabindex="-1">纯计算沙箱 <a class="header-anchor" href="#纯计算沙箱" aria-label="Permalink to “纯计算沙箱”">​</a></h1><p>with KossJS(capabilities=KossJS.KOSS_CAP_SANDBOX) as koss: result = koss.eval(&quot;1 + 1&quot;) print(result) # 正常工作</p><h1 id="只允许网络-加密" tabindex="-1">只允许网络 + 加密 <a class="header-anchor" href="#只允许网络-加密" aria-label="Permalink to “只允许网络 + 加密”">​</a></h1><p>with KossJS(capabilities=KossJS.KOSS_CAP_ALL_NET | KossJS.KOSS_CAP_ALL_CRYPTO) as koss: result = koss.run_async(&#39;&#39;&#39; (async () =&gt; { const r = await fetch(&quot;<a href="https://api.github.com/users/github" target="_blank" rel="noreferrer">https://api.github.com/users/github</a>&quot;); const d = await r.json(); return d.login; })(); &#39;&#39;&#39;) `</p><h3 id="_4-3-使用审核回调" tabindex="-1">4.3 使用审核回调 <a class="header-anchor" href="#_4-3-使用审核回调" aria-label="Permalink to “4.3 使用审核回调”">​</a></h3><p>`python from kossjs_interface import KossJS, JsError</p><p>def my_audit(target: str, args: list[str], pwd: str | None) -&gt; bool: if target == &quot;fs.readFile&quot;: return args[0].startswith(&quot;/tmp/sandbox/&quot;) return True</p><p>koss = KossJS(capabilities=KossJS.KOSS_CAP_ALL_FS) koss.set_audit_mask(KossJS.FS_READ) koss.check_sandbox(my_audit)</p><p>try: koss.eval(&quot;require(&#39;fs&#39;).readFileSync(&#39;/etc/passwd&#39;)&quot;) except JsError as e: print(f&quot;Blocked: {e}&quot;) # KossSecurityError `</p><h3 id="_4-4-使用-node-js-模块" tabindex="-1">4.4 使用 Node.js 模块 <a class="header-anchor" href="#_4-4-使用-node-js-模块" aria-label="Permalink to “4.4 使用 Node.js 模块”">​</a></h3><p>`python from kossjs_interface import KossJS</p><p>with KossJS() as koss: # 使用路径模块 code = &#39;&#39;&#39; const path = require(&quot;path&quot;); path.join(&quot;/home&quot;, &quot;user&quot;, &quot;file.txt&quot;); &#39;&#39;&#39; result = koss.eval(code) print(result) # 输出: /home/user/file.txt `</p><h3 id="_4-5-注册原生函数" tabindex="-1">4.5 注册原生函数 <a class="header-anchor" href="#_4-5-注册原生函数" aria-label="Permalink to “4.5 注册原生函数”">​</a></h3><p>`python from kossjs_interface import KossJS</p><p>def python_add(a, b): return str(int(a) + int(b))</p><p>with KossJS() as koss: koss.register_function(&quot;python_add&quot;, python_add) result = koss.eval(&quot;python_add(10, 20)&quot;) print(result) # 输出: 30 `</p><hr><h2 id="_5-内存管理" tabindex="-1">5. 内存管理 <a class="header-anchor" href="#_5-内存管理" aria-label="Permalink to “5. 内存管理”">​</a></h2><h3 id="回调函数引用管理" tabindex="-1">回调函数引用管理 <a class="header-anchor" href="#回调函数引用管理" aria-label="Permalink to “回调函数引用管理”">​</a></h3><p>每次调用 <em><strong>register_function</strong></em> 时，若提供了回调函数，会通过 <em><strong>ctypes.CFUNCTYPE</strong></em> 创建一个 C 可调用对象。</p><p>Python 接口通过以下方式管理这些引用：</p><ul><li>回调对象被保存在 <em><strong>self._callbacks</strong></em> 列表中</li><li>这些引用会随着 <em><strong>KossJS</strong></em> 实例一起被 Python 垃圾回收器自动清理</li><li>无需手动干预或调用额外的清理方法</li></ul><hr><h2 id="_6-注意事项" tabindex="-1">6. 注意事项 <a class="header-anchor" href="#_6-注意事项" aria-label="Permalink to “6. 注意事项”">​</a></h2><ol><li><strong>库路径</strong>：若自动猜测失败，需显式传入正确路径。</li><li><strong>返回值</strong>：所有执行方法返回字符串结果，调用方需自行解析。</li><li><strong>异常处理</strong>：JavaScript 错误会引发 <em><strong>JsError</strong></em> 异常。</li><li><strong>多线程环境</strong>：不同线程使用不同的 <em><strong>KossJS</strong></em> 实例是安全的。</li><li><strong>模块加载</strong>：需要 <em><strong>with_modules=True</strong></em> 才能使用 <em><strong>require()</strong></em>。</li><li><strong>Async/Await</strong>：异步代码需要使用 <em><strong>run_async()</strong></em> 执行。</li><li><strong>稳定模式</strong>：生产环境使用默认 <em><strong>stable=True</strong></em>，开发/调试使用 <em><strong>stable=False</strong></em>。</li></ol><hr><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to “7. 常见问题”">​</a></h2><p><strong>Q: 为什么我的代码返回 &quot;undefined&quot;?</strong> A: JavaScript 函数默认返回 undefined。如果需要返回值，确保有 return 语句。</p><p><strong>Q: 如何处理异步 fetch?</strong> A: 使用 un_async() 方法执行异步代码，它会驱动事件循环直到 Promise 完成。</p><p><strong>Q: 需要并发执行多个脚本怎么办？</strong> A: 创建多个 <em><strong>KossJS</strong></em> 实例，每个管理一组脚本。它们独立运行。或配合 <em><strong>threading</strong></em> 模块执行。</p><p><strong>Q: 为什么 require() 不工作？</strong> A: 确保创建实例时设置 <em><strong>with_modules=True</strong></em>。</p><p><strong>Q: 如何启用 FFI 功能？</strong> A: 创建实例时设置 <em><strong>stable=False</strong></em>。</p><p><strong>Q: 如何限制实例的权限？</strong> A: 使用 <em><strong>capabilities</strong></em> 参数设置能力位掩码。</p><hr><p>如有问题，请提交 issue。</p>',160)])])}const _=t(r,[["render",n]]);export{p as __pageData,_ as default};
